package company.backend.entity;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.Table;

/**
 * An image uploaded through the administration portal.
 *
 * <p>The stored {@code filename} is generated by the server and is the only
 * name ever used to build a path. The uploader's original filename is kept only
 * as a display label and is never used for storage, so a crafted name such as
 * {@code ../../application.properties} cannot influence where a file lands.
 */
@Entity
@Table(name = "content_images", indexes = {
		@Index(name = "idx_content_images_created_at", columnList = "createdAt") })
public class ContentImage {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	/** Server generated, extension derived from the validated type. Never user supplied. */
	@Column(name = "filename", nullable = false, unique = true, length = 120)
	private String filename;

	/** The uploader's original name, for display only. */
	@Column(name = "original_name", nullable = false, length = 255)
	private String originalName;

	/** Verified by decoding the image, not by trusting the request. */
	@Column(name = "mime_type", nullable = false, length = 60)
	private String mimeType;

	@Column(name = "size_bytes", nullable = false)
	private long sizeBytes;

	@Column(name = "width", nullable = false)
	private int width;

	@Column(name = "height", nullable = false)
	private int height;

	/** Alternative text. Required, so a meaningful image is never unlabelled. */
	@Column(name = "alt_text", nullable = false, length = 300)
	private String altText;

	@Column(name = "caption", length = 300)
	private String caption;

	@Column(name = "uploaded_by", nullable = false, length = 60)
	private String uploadedBy;

	@Column(name = "created_at", nullable = false)
	private Instant createdAt;

	protected ContentImage() {
		// Required by JPA.
	}

	public ContentImage(String filename, String originalName, String mimeType, long sizeBytes, int width, int height,
			String altText, String caption, String uploadedBy, Instant createdAt) {
		this.filename = filename;
		this.originalName = originalName;
		this.mimeType = mimeType;
		this.sizeBytes = sizeBytes;
		this.width = width;
		this.height = height;
		this.altText = altText;
		this.caption = caption;
		this.uploadedBy = uploadedBy;
		this.createdAt = createdAt;
	}

	public Long getId() {
		return this.id;
	}

	public String getFilename() {
		return this.filename;
	}

	public String getOriginalName() {
		return this.originalName;
	}

	public String getMimeType() {
		return this.mimeType;
	}

	public long getSizeBytes() {
		return this.sizeBytes;
	}

	public int getWidth() {
		return this.width;
	}

	public int getHeight() {
		return this.height;
	}

	public String getAltText() {
		return this.altText;
	}

	public void setAltText(String altText) {
		this.altText = altText;
	}

	public String getCaption() {
		return this.caption;
	}

	public void setCaption(String caption) {
		this.caption = caption;
	}

	public String getUploadedBy() {
		return this.uploadedBy;
	}

	public Instant getCreatedAt() {
		return this.createdAt;
	}
}